    svs_compliance_eu: ['Special ad categories confirmed · EU transparency: {beneficiary}.', 'Speciale advertentiecategorieën bevestigd · EU-transparantie: {beneficiary}.', 'Besondere Anzeigenkategorien bestätigt · EU-Transparenz: {beneficiary}.', 'Catégories spéciales de publicités confirmées · Transparence UE : {beneficiary}.', 'Categorías especiales de anuncios confirmadas · Transparencia de la UE: {beneficiary}.', 'Categorias especiais de anúncios confirmadas · Transparência da UE: {beneficiary}.'],
    svs_identity_meta: ['Facebook Page connected.', 'Facebook-pagina gekoppeld.', 'Facebook-Seite verbunden.', 'Page Facebook connectée.', 'Página de Facebook conectada.', 'Página do Facebook ligada.'],
